const vector3df k_gravity = vector3df(0.0f, -9.8f * 3, 0.0f);
const float k_flyingTime = 0.6f;
const float k_maxDamagePerUnit = 9999.0f;

const float k_spriteScale = 1.5f;

const int k_touch_x = 175;
const int k_touch_y = 0;
const int k_touch_w = 100;
const int k_touch_h = 90;


class CFireballNode : public CEmptySceneNode
{
public:
	CFireballNode (CFireball* fb)
	{
		m_fireball = fb;
	}

	~CFireballNode ()
	{
	}

	video::SMaterial& getMaterial(u32 num)
	{
		return *m_fireball->getSprite()->_material;
	}

	u32 getMaterialCount() const
	{
		return 1;
	}

	void OnRegisterSceneNode ()
	{
		SceneManager->registerNodeForRendering(this, &getMaterial(0), 0, ESNRP_TRANSPARENT);
	}

	void render (void* renderData)
	{
		m_fireball->draw();
	}

private:
	CFireball* m_fireball;
};

void setAdditive (ISceneNode * node)
{
	list<ISceneNode*>::ConstIterator it = node->getChildren().begin();
	for (; it != node->getChildren().end();)
	{
		ISceneNode * child = (*it);
		it++;
		setAdditive(child); 
	}

	for (int i = 0; i < node->getMaterialCount(); ++i)
	{
		node->getMaterial(i).setMaterialType(EMT_TRANSPARENT_ADD_COLOR);
	}
}

CFireball::CFireball() : CWeaponObject(0)
{
	m_velocity = vector3df(0.0f, 0.0f, 0.0f);

	m_Node = new CFireballNode(this);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_Node);

	m_postament = LoadColladaScene("Scenes/Fireball/bowl_gold.bdae");
	cleanNode(m_postament);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_postament);

	m_shadow = LoadColladaScene("Scenes/Goblin/shadow.bdae");
	cleanNode(m_shadow);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_shadow);

	m_light = LoadColladaScene("Scenes/Fireball/fireball_light.bdae");
	cleanNode(m_light);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_light);

	array< scene::ISceneNode *> meshnodes;
	m_SceneManager->getSceneNodesFromType(ESNT_LIGHT, meshnodes, m_light);
	u32 i;
	for (i=0; i<meshnodes.size(); i++)
		meshnodes[i]->remove();

	m_sprite = NULL;

	m_spriteGlow = new ASprite;
	m_spriteGlow->Load("Ingame/fireball_glow");
	m_spriteGlow->_material->setMaterialType(EMT_TRANSPARENT_ADD_COLOR);

	m_burnedGround.setRoot(LoadColladaScene("Scenes/Fireball/burned_ground.bdae"));
	cleanNode(m_burnedGround.getRoot());
	__IRR_SCENE()->getRootSceneNode()->addChild(m_burnedGround.getRoot());

	m_inst.StartAnim(m_sprite, 0, 0, 0);

	m_touch = new CTouchElement(CTouchElement::Type_Drag, 1000);
	m_touch->SetScreenCoordinates(k_touch_x, k_touch_y, k_touch_w, k_touch_h);

	setLevel(WL_None);
	reset();
}

void CFireball::setSpawnPosition(ISceneNode * node)
{
	node->addChild(m_postament);

	m_spawnPosition = node->getAbsolutePosition() + v3f(0,2,0);
	setPosition(m_spawnPosition);
}

void CFireball::reset()
{
	CWeaponObject::reset();

	if (m_level != WL_None)
	{
		m_sprite->_material->setFlag(EMF_ZBUFFER, true);
		m_spriteGlow->_material->setFlag(EMF_ZBUFFER, true);
		setShouldBeVisible(true, false, false);
		setPosition(m_spawnPosition);
		//setState(FS_RespawningToReadyTransition);
		setState(FS_Ready);
	}
	else
	{
		setState(FS_Disabled);
		setShouldBeVisible(false, false, false);
	}

	setVisible(true);

	m_bounce = 0;
	m_bounceUnitsHit = 0;
}

CFireball::~CFireball()
{
	m_Node->remove();
	m_Node->drop();

	m_postament->remove();
	m_postament->drop();

	m_shadow->remove();
	m_shadow->drop();

	m_light->remove();
	m_light->drop();

	m_burnedGround.getRoot()->remove();
	m_burnedGround.getRoot()->drop();

	SAFE_DEL(m_sprite);
	SAFE_DEL(m_spriteGlow);

	SAFE_DEL(m_touch);
}

void CFireball::adjustStats(IAttributes* attributes)
{
	const char* cooldown[] = { "CooldownEasy", "CooldownMedium", "CooldownHard" };
	int difficulty = (int)(CPlayfield::GetInstance()->getDifficulty());
	m_stat_cooldown =	attributes->getAttributeAsFloat( cooldown[difficulty] );

	m_stat_radius =		attributes->getAttributeAsFloat("DamageRadius");
	m_stat_maxDamage =	attributes->getAttributeAsInt("MaxDamage");
	m_stat_maxBurn =	attributes->getAttributeAsInt("MaxBurn");
	m_stat_bounce =		attributes->getAttributeAsInt("Bounce");

	if (!m_sprite)
	{
		m_sprite = new ASprite();
		m_sprite->Load("Ingame/fireball");
		m_inst.SetASprite(m_sprite);
	}
	
	switch (m_level)
	{
	case WL_1: m_sprite->LoadTexture("Sprites/Ingame/fireball_small.png"); break;
	case WL_2: m_sprite->LoadTexture("Sprites/Ingame/fireball_medium.png"); break;
	case WL_3: m_sprite->LoadTexture("Sprites/Ingame/fireball_big.png"); break;
	}
}

void CFireball::update(f32 time)
{
	CWeaponObject::update(time);

	m_drawItems.set_used(0);
	m_stateTime += time;
	m_inst.Update(time);

	if (m_burnedGroundTimer > 0.0f)
	{
		m_burnedGroundTimer -= time;
		if (m_burnedGroundTimer < 0.0f)
		{
			m_burnedGround.setAnim(1, false);
		}
	}

	m_touch->SetEnabled( isDragable() );

	CPlayfield* playfield = CPlayfield::GetInstance();
	line3df path = playfield->getPath();
	line3df extendedPath = path;
	extendedPath.end += path.getVector().setLength(6.0f);
	vector3df pathDir = path.getVector();

	switch (m_state)
	{
		case FS_Shop:
		case FS_Ready:
		{
			m_sprite->_material->setFlag(EMF_ZBUFFER, true);
			m_spriteGlow->_material->setFlag(EMF_ZBUFFER, true);
			m_drawItems.push_back(PosScale(getPosition(), k_spriteScale));
			if (m_touch->IsActive())
			{
				PlaySfx( SFX_DEFENSE_FIREBALL_AIM );

				startDrag(m_touch);
				CPlayfield::GetInstance()->getChallenge()->specialWeaponUsed();
				m_velocity = v3f(0,0,0);
				m_smoothVelocity = v3f(0,0,0);
			}
			break;
		}

		case FS_Dragged:
		{
			m_sprite->_material->setFlag(EMF_ZBUFFER, false);
			m_spriteGlow->_material->setFlag(EMF_ZBUFFER, false);

			position2di spawn2d = screenFrom3DPos(m_spawnPosition);
			position2di touch;
			m_touch->GetTouchPos_Current(touch.X, touch.Y);
			touch = touch + m_dragOffset;

			vector2df diff(touch.X - spawn2d.X, touch.Y - spawn2d.Y);
			if (m_touch->IsActive())
			{
				line3df ray = m_SceneManager->getSceneCollisionManager()->getRayFromScreenCoordinates(touch);

				vector3df newPos;
				playfield->getFlyingPlane().getIntersectionWithLine(ray.start, ray.getVector(), newPos);

				if (playfield->getCastlePlane().classifyPointRelation(newPos) != ISREL3D_FRONT)
				{
					playfield->getCastlePlane().getIntersectionWithLine(newPos, path.getVector(), newPos);
				}
				if (playfield->getGroundPlane().getDistanceTo(newPos) < 1.5f)
				{
					playfield->getGroundPlane().getIntersectionWithLine(newPos, v3f(0,1,0), newPos);
					newPos += v3f(0, 1.5f, 0);
				}

				v3f newVelocity = (newPos - getPosition()) / time;
				if (newVelocity.getLength() > 25.0f)
					newVelocity.setLength(25.0f);
				v3f acceleration = (newVelocity - m_velocity) / time;

				m_velocity = newVelocity;

				float k = powf(0.001f, time);
				m_smoothVelocity = k * m_smoothVelocity + (1 - k) * m_velocity;

				setPosition(getPosition() + m_velocity * time);

				calculateTail(v3f(0, 0, 0), m_smoothVelocity);
			}
			else
			{
				setState(FS_Flying);

				PlaySfx( SFX_DEFENSE_FIREBALL_FLY );

				calculateTail(v3f(0, 0, 0), m_smoothVelocity);
			}
			break;
		}

		case FS_Flying:
		{
			m_velocity += k_gravity * time;
			vector3df oldPos = getPosition();
			vector3df newPos = getPosition() + m_velocity * time;
			setPosition(newPos);
			//m_cometTail->SetPosition(getPosition());

			calculateTail(k_gravity, m_velocity);

			bool hit = false;

			/// Castle Hit Test
			if (playfield->getCastlePlane().classifyPointRelation(newPos) == ISREL3D_BACK)
			{
				playfield->getCastlePlane().getIntersectionWithLine(oldPos, (newPos - oldPos), newPos);
				setPosition(newPos);

				m_hit_normal = playfield->getCastlePlane().Normal;
				m_hit_normal.normalize();
				hit = true;
			}
				
			/// Ground Hit Test
			if (playfield->getGroundPlane().classifyPointRelation(newPos) == ISREL3D_BACK)
			{
				playfield->getGroundPlane().getIntersectionWithLine(oldPos, (newPos - oldPos), newPos);
				setPosition(newPos);

				m_hit_normal = playfield->getGroundPlane().Normal;
				m_hit_normal.normalize();
				hit = true;
			}

			if (hit)
			{
				explode();

				PlaySfx( SFX_DEFENSE_FIREBALL_IMPACT );

			}
			break;
		}

		case FS_Dying:
		{
			setShouldBeVisible(true, false, true);

			m_velocity += k_gravity * time;
			vector3df newPos = getPosition() + m_velocity * time;
			setPosition(newPos);
			calculateTail(k_gravity, m_velocity);
			//m_cometTail->SetPosition(getPosition());

			if (m_drawItems.size() == 0)
			{
				//m_cometTail->UnloadParticleSystem();
				setShouldBeVisible(false, false, m_visibleEffect);
				setState(FS_Respawning);
				//RemoveParticleSystem(m_cometTail);
			}
			break;
		}

		case FS_Respawning:
		{
			if (m_stateTime > m_stat_cooldown || CGameConfig::NoWeaponCD)
			{
				m_sprite->_material->setFlag(EMF_ZBUFFER, true);
				m_spriteGlow->_material->setFlag(EMF_ZBUFFER, true);
				setShouldBeVisible(true, false, false);
				setPosition(m_spawnPosition);
				setState(FS_RespawningToReadyTransition);
			}
			break;
		}

		case FS_RespawningToReadyTransition:
		{
			m_drawItems.push_back(PosScale(getPosition() - (0.4f - m_stateTime) * vector3df(0, 2.0f, 0), k_spriteScale * (m_stateTime / 0.4f)));
			if (m_stateTime > 0.4f)
			{
				setState(FS_Ready);
			}
			break;
		}
	}

	if (m_state == FS_Dragged || m_state == FS_Flying)
	{
		v3f pos = getPosition();
		p2i screen = screenFrom3DPos(pos);
		line3df ray = m_SceneManager->getSceneCollisionManager()->getRayFromScreenCoordinates(screen);

		if (playfield->getFlyingPlane().classifyPointRelation(pos) == ISREL3D_FRONT)
		{
			playfield->getFlyingPlane().getIntersectionWithLine(ray.start, ray.getVector(), pos);
			setPosition(pos);
		}
	}

	if (m_state == FS_Dragged || m_state == FS_Flying)
	{
		v3f shadowPos;
		playfield->getGroundPlane().getIntersectionWithLine(getPosition(), v3f(0,1,0), shadowPos);
		m_shadow->setPosition(shadowPos);
		m_light->setPosition(shadowPos);
		float distanceFromGround = playfield->getGroundPlane().getDistanceTo(getPosition());
		float scale = 2.0f - 0.1f * distanceFromGround;
		CLAMP(scale, 0.4f, 2.0f);
		m_shadow->setScale(v3f(scale, scale, scale));
		m_light->setScale(2.0f * v3f(scale, scale, scale));
	}

	m_burnedGround.updateAtEndOfFrame(time);
}

void CFireball::elfArrowHit ()
{
	if (m_state == FS_Ready)
	{
		setShouldBeVisible(false, false, m_visibleEffect);
		setState(FS_Respawning);

		PlaySfx( SFX_ATTACK_SABOTAGE_WEAPON );
	}
}

ASprite* CFireball::getSprite ()
{
	return m_sprite;
}

ASprite* CFireball::getSpriteGlow ()
{
	return m_spriteGlow;
}

void CFireball::calculateTail (v3f accel, v3f velocity)
{
	m_drawItems.set_used(0);

	float t = 0.0f;

	v3f vel = velocity;

	const float timestep = 0.02f;
	vector3df pos = getPosition();
	for (int i = 0; i < 8; ++i)
	{
		m_drawItems.push_back(PosScale(pos, k_spriteScale - (i / 8.0f) * 0.7f + (i > 0) * 0.3f));
		pos -= vel * timestep;
		vel -= accel * timestep;
		t -= timestep;
	}

	// clip with ground
	while (!m_drawItems.empty() &&
		(CPlayfield::GetInstance()->getGroundPlane().classifyPointRelation(m_drawItems[0].pos) == ISREL3D_BACK ||
		 CPlayfield::GetInstance()->getCastlePlane().classifyPointRelation(m_drawItems[0].pos) == ISREL3D_BACK))
	{
		m_drawItems.erase(0);
	}
}

int RandInt (int min, int max);

void FireballExplosion (v3f position, float radius, float maxDamage, float elfSurvivalChance, int* unitsHitByKind, int* curBounceUnitsHit, float scale = 1.0f)
{
	// The fireball should explode and throw all units near it to make things interesting.
	// However, it should only do k_maxDamage damage at most, so some units must survive.
	// To make things more interesting, the units that will die can do so in several ways:
	//   1. fall on the path and die normally
	//   2. fall in the river on either side of the path and make a splash
	//   3. fall in the mouth of the hydra if its hungry
	//   4. fall towards the viewer disappearing in the near clip plane
	//   5. go splat on the castle wall
	// However the unit must not fall in any other places which are considered uncool,
	// like on a slope, on the griffin or any place it looks awkward or is clipped.
	// And of course the units that do survive must only fall on the path.

	// explodes a little below the ground to throw units up and not just left/right
	v3f explosionPos = position + v3f(0, -5, 0);

	v3f waterDummies[3];
	waterDummies[0] = CPlayfield::GetInstance()->getDummy("d_water_01")->getAbsolutePosition();
	waterDummies[1] = CPlayfield::GetInstance()->getDummy("d_water_02")->getAbsolutePosition();
	waterDummies[2] = CPlayfield::GetInstance()->getDummy("d_water_03")->getAbsolutePosition();
	int indices[3] = { 0, 1, 2 };
	std::random_shuffle(indices, indices + 2);
	int waterIndex = 0;

	float damageDone = 0.0f;
	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
	{
		CUnit* unit = *it;
		float dist = (unit->getAbsolutePosition() - position).getLength();
		if (dist < radius && unit->isPetrified())
			unit->unpetrify(true);
		else if (dist < radius && unit->canBeDamagedByFireball())
		{
			// send them flying!
			v3f vel = unit->getAbsolutePosition() - explosionPos;
			float throwPower = 34;
			vel.setLength(throwPower * (radius - dist) / radius);
			bool harmless = damageDone >= maxDamage;

			if (!harmless && unit->getUnitKind() == UK_Elf && RandFloat(0, 1) < elfSurvivalChance)
			{
				unit->elfJump(1.0f);
			}
			else if (harmless)
			{
				unit->throwUnit(unit->projectVectorToFlyingPlane(vel), true);
			}
			else
			{
				v3f hitPos = unit->getFallPosition(vel);
				bool hitPosOnPath = unit->isPositionOnPath(hitPos);
				if (!hitPosOnPath)
					vel = unit->projectVectorToFlyingPlane(vel);
				damageDone += unit->damageUnit(k_maxDamagePerUnit, UDS_Fireball);
				unit->throwUnit(vel, false);
				if (unit->getState() != US_FallingOnHydra)
				{
					// randomly throw the unit very far/near, in the water on on the path
					int rnd = RandInt(0, 100);
					if (waterIndex < 3 && rnd < 50)
					{
						// throw in water
						unit->damageUnit(k_maxDamagePerUnit, UDS_Fireball);
						unit->throwUnitInWater(waterDummies[indices[waterIndex++]]);
					}
					else if (rnd < 70)
					{
						// throw very far
						damageDone += unit->damageUnit(k_maxDamagePerUnit, UDS_Fireball);
						unit->throwUnitOnForTime(unit->getAbsolutePosition() - v3f(0, 0, 10), 0.6f);
					}
					else if (rnd < 101 && unit->getVelocity().X > 0)
					{
						// go splat on castle
						unit->healUnit(1.0f);
						unit->throwUnit(v3f(35, RandFloat(20.0f, 30.0f), 0), false);
					}
					else
					{
						// just let it fly
					}
					++unitsHitByKind[unit->getUnitKind()];
				}

				(*curBounceUnitsHit)++;

				v3f vel = unit->getVelocity();
				float angle = atan2(-vel.X, vel.Z) + 0.5f * PI;
				unit->getSceneNode()->setRotation(quaternion(0, angle, 0) * unit->getSceneNode()->getRotation());
			}
		}
	}
	

	// kill the ice
	if (CPlayfield::GetInstance()->getIceball()->isGroundSlippery(position))
		CPlayfield::GetInstance()->getIceball()->removeIce();

	ParticleSystem* ps = AddParticleSystem("explode_new");
	ps->SetZBuffer(false);
	ps->SetPosition(position + v3f(0, 1.0, 0));
	ps->SetScale(0.075f * 0.75f * scale);
	ps->Restart();
}

void CFireball::explode ()
{
	int unitsHitByKind[UK_Unknown + 1] = { 0 };
	int curBounceUnitsHit = 0;
	int difficulty = CPlayfield::GetInstance()->getDifficulty();
	FireballExplosion(getPosition(), m_stat_radius, m_stat_maxDamage, 0.8f - 0.1f * m_level - 0.2 * (2 - difficulty), unitsHitByKind, &curBounceUnitsHit);
	CPlayfield::GetInstance()->getChallenge()->unitsWereKilledByWeapon(UDS_Fireball, unitsHitByKind);

	/// Burn Ground
	const f32 height = CPlayfield::GetInstance()->getGroundPlane().getDistanceTo( getPosition() );
	if (height < 2.0f)
	{
		m_burnedGroundTimer = 1.5f;
		v3f pos = getPosition() + v3f(0, -height, 0);
		m_burnedGround.getRoot()->setPosition(pos);
		m_burnedGround.setAnim(0, false);
	}

	bool die = true;

	if (m_bounce < m_stat_bounce)
	{
		if( curBounceUnitsHit > 0 ) 
			m_bounceUnitsHit++;

		m_bounce++;

		const f32 speed = m_velocity.getLength() * 0.7f;
		const f32 speedMin = 10.0f;
		const f32 speedMax = 40.0f;

		if (height > 2.0f || speed >= speedMin)
		{
			m_velocity.setLength(speed);
			m_velocity = -m_velocity;

			quaternion q;
			q.rotationFromTo(m_velocity, m_hit_normal);
			q.slerp(quaternion(), q, -1.4f);

			m_velocity = q * m_velocity;
			die = false;
		}
	}
	else
	{
		/// Set achievement 'Fireball Master'
		if( m_bounceUnitsHit == WL_3 && curBounceUnitsHit > 0 )
		{
			CPlayfield::GetInstance()->addMoney(0, 50, getPosition(), _TXT(INGAME_GREAT));
			__ACHIEVEMENTS()->setAchieved( "Fireball Master" );
		}
	}
	
	if (die)
	{
		setState(FS_Dying);
	}
}

void CFireball::draw()
{
	if (!m_Node->isVisible())
		return;

	const f32 bounceScale = 1.0f - 0.15f * m_bounce;
	const f32 baseScale = m_baseScale * m_scale * bounceScale;
	v3f campos = __IRR_SCENE()->getActiveCamera()->getAbsolutePosition();

	for (int i = m_drawItems.size() - 1; i >= 0; --i)
	{
		const f32 scale = baseScale * m_drawItems[i].scale;
		v3f pos = pos = m_drawItems[i].pos + (campos - m_drawItems[i].pos).setLength(1.5f);

		if (i == 0)
		{
			// draw glow!
			m_spriteGlow->PaintFrame3D(0, pos, 0, 0, 0, scale * SPRITE_SCALE_3D, scale * SPRITE_SCALE_3D);
		}

		if (i != 0 && m_drawItems.size() > 1)
		{
			m_inst.GetASprite()->PaintFrame3D(i + INGAME_F_FIREBALL_FIRST_TAIL + (8 - m_drawItems.size()),
				pos, 0, 0, 0, scale * SPRITE_SCALE_3D, scale * SPRITE_SCALE_3D);
		}
		else
		{
			m_inst.Draw3D(pos, scale);
		}
	}
}

void CFireball::setVisible(bool visible)
{
	m_visible = visible;
	m_Node->setVisible(m_visible && m_visibleObject);
	bool isNight = CPlayfield::GetInstance()->GetDayTime() >= 0.85f;
	m_shadow->setVisible(m_visible && m_visibleShadow && !isNight);
	m_light->setVisible(m_visible && m_visibleShadow && isNight);
	m_postament->setVisible(m_visible && (m_level != WL_None));
}

bool CFireball::isVisible()
{
	return m_visible;
}

void CFireball::setShouldBeVisible(bool object, bool shadow, bool effect)
{
	m_visibleObject = object;
	m_visibleShadow = shadow;
	m_visibleEffect = effect;
	setVisible(m_visible);
}

float CFireball::getCooldown()
{
	if (m_state != FS_Respawning)
		return 0.0f;

	return max(0.0f, 1.0f - m_stateTime / m_stat_cooldown);
}

void CFireball::setState(EFireballState state)
{
	m_state = state;
	m_stateTime = 0;

	switch (m_state)
	{
	case FS_Respawning:
		m_bounce = 0;
		m_bounceUnitsHit = 0;
		break;
	}
}

EFireballState CFireball::getState()
{
	return m_state;
}

bool CFireball::isDragable()
{
	return m_state == FS_Ready || m_state == FS_Dragged;
}

void CFireball::startDrag (CTouchElement * touch)
{
	setState(FS_Dragged);
	position2di touchPos;
	m_touch->GetTouchPos_Current(touchPos.X, touchPos.Y);
	m_dragOffset = p2i(0,0);//getScreenPosition() - touchPos;
	setShouldBeVisible(true, true, false);
}

position2di CFireball::getScreenPosition()
{
	return screenFrom3DPos(getPosition());
}

CTouchElement* CFireball::getTouch ()
{
	return m_touch;
}

void CFireball::setShopState ()
{
	setState(FS_Shop);
	m_touch->SetEnabled(false);
}

void CFireball::setShopHighlight(f32 power)
{
	SColor emissive = SColor(0xAAAAAAAA).getInterpolated(SColor(0x00000000), power);

	setEmissiveColor(getPostament(), emissive);
	getSprite()->_material->setFlag(EMF_LIGHTING, true);
	getSprite()->_material->setEmissiveColor(emissive);
	getSpriteGlow()->_material->setFlag(EMF_LIGHTING, true);
	getSpriteGlow()->_material->setEmissiveColor(emissive);
}

s32 CFireball::PlaySfx(s32 soundId, bool loop, s32 fadeInTime)
{
	CSoundManager* sm = __MGR_SOUNDS();

	const char* soundName = sm->GetSoundNameFromIndex( soundId );
	GX_ASSERT(soundName != 0);
	
	IAttributes* configAttr = CGameConfig::GetInstance()->getAttributes( L"soundsconfig",  stringw(soundName));
	if(configAttr != 0 && configAttr->getAttributeAsInt("Obligatory") == 0)
	{
		position2di pos = getScreenPosition();
		//rect<s32> viewport = m_SceneManager->getVideoDriver()->getViewPort();
		rect<s32> viewport(0, 0, GAME_SCREEN_W, GAME_SCREEN_H);
		if(!viewport.isPointInside(pos))
			return CPlayfield::GetInstance()->PlaySfx(soundId, loop, fadeInTime, 100);
	}

	return CPlayfield::GetInstance()->PlaySfx(soundId, loop, fadeInTime);
}
